<template><view v-if="summary" class="page"><view class="card"><view class="page-title">{{ summary.task.title }}</view><view class="muted">{{ summary.task.description }}</view></view><view v-for="m in summary.members" :key="m.userId" class="card"><view class="row-between"><text>{{ m.nickname }}</text><text :class="m.signed?'ok':'no'">{{ m.signed?'已签到':'未签到' }}</text></view><view v-if="m.record" class="muted">{{ displayTime(m.record.signedAt) }} {{ m.record.address||'' }}</view><image v-if="m.record?.photoUrl" class="proof" :src="m.record.photoUrl" mode="aspectFill" /></view></view></template>
<script setup lang="ts">import{ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{api}from'@/services/api';import{displayTime}from'@/utils/time';const summary=ref<any>(null);onLoad(async(o:any)=>summary.value=await api(`/sign-tasks/${Number(o.taskId)}/summary`))</script><style scoped lang="scss">.ok{color:$success}.no{color:$text-muted}.proof{width:180rpx;height:180rpx;border-radius:12rpx;margin-top:16rpx}</style>
